<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$downloads=load_json('downloads.json',[]);$daily=[];foreach($downloads as $download){if(!is_array($download))continue;$day=(string)substr((string)$download['downloaded_at'],0,10);$daily[$day]=($daily[$day]??0)+1;}ksort($daily);$chartValues=array_values($daily);$chartLabels=array_keys($daily);?><main class="admin-shell"><aside class="admin-sidebar" data-admin-sidebar><div class="admin-brand"><a class="brand" href="<?= e(app_url('index.php')) ?>"><span class="brand-mark"><i></i><i></i></span><span>2B2X</span></a></div><nav class="admin-nav"><a href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a href="<?= e(app_url('admin/users.php')) ?>">Users</a><a href="<?= e(app_url('admin/releases.php')) ?>">Releases</a><a class="active" href="<?= e(app_url('admin/downloads.php')) ?>">Downloads</a><a href="<?= e(app_url('admin/changelog.php')) ?>">Changelog</a><a href="<?= e(app_url('admin/blog.php')) ?>">Blog</a><a href="<?= e(app_url('admin/support.php')) ?>">Support</a><a href="<?= e(app_url('admin/settings.php')) ?>">Settings</a></nav><div class="admin-sidebar-footer"><a class="button button-ghost button-small" href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></div></aside><div class="admin-main"><header class="admin-topbar"><button class="menu-toggle" data-admin-toggle aria-label="Open admin menu"><span></span><span></span></button><div><h1>Download analytics</h1><small style="color:var(--subtle)">Installation activity and release usage</small></div><span class="status-pill">Anonymized</span></header><div class="admin-content"><section class="admin-metrics"><div class="admin-metric"><span>Total downloads</span><strong><?= count($downloads) ?></strong><small>All records</small></div><div class="admin-metric"><span>Unique users</span><strong><?= count(array_filter($downloads,fn($d)=>is_array($d)&&!empty($d['user_id']))) ?></strong><small>Authenticated</small></div><div class="admin-metric"><span>Guest downloads</span><strong><?= count(array_filter($downloads,fn($d)=>is_array($d)&&empty($d['user_id']))) ?></strong><small>Without login</small></div><div class="admin-metric"><span>Latest release</span><strong><?= e((string)current_release()['version']??'—') ?></strong><small>Current product</small></div></section><section class="admin-grid"><div class="admin-card"><h2>Downloads by day</h2><p>Request activity represented in a native canvas chart.</p><div class="chart"><canvas data-chart="downloads" data-chart-values="<?= e(json_encode($chartValues,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>" data-chart-labels="<?= e(json_encode($chartLabels,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>" aria-label="Download chart"></canvas></div></div><div class="admin-card"><h2>By release</h2><p>Current distribution volume.</p><?php $groups=[];foreach($downloads as $download){if(!is_array($download))continue;$version=release_by_id((string)$download['release_id'])['version']??'Unknown';$groups[$version]=($groups[$version]??0)+1;}foreach($groups as $version=>$count):?><div class="mini-stat"><span><?= e($version) ?></span><strong><?= $count ?></strong></div><?php endforeach; if(!$groups):?><div class="empty-state"><h3>No download data</h3><p>Downloads will appear here.</p></div><?php endif; ?></div></section><section class="admin-card admin-table-card"><h2>Download records</h2><p>Activity is stored without raw IP addresses.</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Release</th><th>Platform</th><th>Architecture</th><th>Account</th></tr></thead><tbody><?php if(!$downloads):?><tr><td colspan=5><div class="empty-state"><h3>No downloads yet</h3><p>Installer requests will appear here.</p></div></td></tr><?php else:foreach(array_reverse($downloads) as $download):?><tr><td><?= e(format_date((string)$download['downloaded_at'])) ?></td><td><?= e((string)(release_by_id((string)$download['release_id'])['version']??'Unknown')) ?></td><td>Windows</td><td><?= e((string)$download['architecture']) ?></td><td><?= $download['user_id']?'Signed in':'Guest' ?></td></tr><?php endforeach;endif; ?></tbody></table></div></section></div></div><script src="<?= e(app_url('assets/js/charts.js')) ?>" defer></script><?php require_once __DIR__.'/../includes/footer.php'; ?>
